import {useState} from 'react';
import {Calendar} from '@gravity-ui/date-components';
import type {DateTime} from '@gravity-ui/date-utils';
import {Box, Flex, Text} from '@gravity-ui/uikit';

export function App() {
  const [selected, setSelected] = useState<DateTime | null>(null);

  return (
    <Box spacing={{p: 6}}>
      <Flex direction="column" gap={4}>
        <Text variant="header-1">Выбор даты</Text>
        <Calendar value={selected} onUpdate={setSelected} />
        <Text variant="body-2" color="secondary">
          {selected ? `Выбрана дата: ${selected.format('DD.MM.YYYY')}` : 'Дата не выбрана'}
        </Text>
      </Flex>
    </Box>
  );
}

